function route(before=Infinity){const years=Object.keys(P.choices).map(Number).filter(y=>y<before).sort((a,b)=>a-b),counts={explore:0,deepen:0,connect:0},bag=Object.fromEntries(dimensions.map(d=>[d.key,0]));for(const year of years){const c=getYear(year).choices.find(c=>c.id===P.choices[year]);if(!c)continue;if(Object.hasOwn(counts,c.id))counts[c.id]++;for(const[k,n]of Object.entries(c.effect||{}))if(Object.hasOwn(bag,k))bag[k]+=Number(n);}const high=Math.max(...Object.values(counts)),tied=Object.keys(counts).filter(k=>counts[k]===high),id=high?years.slice().reverse().map(y=>P.choices[y]).find(id=>tied.includes(id)):null;return{years,counts,bag,id,name:{explore:'探路者',deepen:'筑造者',connect:'连接者'}[id]||'尚未落笔'};}
