function completeAction(y,action){P.actions[y.year]=true;P.frames[y.year]=2;state.frame=2;save();closeDialog('action-dialog');renderFrames();const memory=comicFor(y).memory||{name:`${y.year}的一页纸`,description:action.completeText||'你为这一年的故事，留下了一个自己的动作。'};$('#reward-name').textContent=memory.name;$('#reward-description').textContent=memory.description;$('#reward-year').textContent=String(y.year);setImage($('#reward-image'),yearScene(y));openDialog('reward-dialog');pageSound();}
function openChoices(){const y=current(),r=route(y.year),selected=P.choices[y.year];$('#choice-kicker').textContent=`${y.year} · 最后一页，留给你的选择`;$('#choice-title').textContent='这一年，你想怎么走？';$('#choice-memory').textContent=carryNarration(y);$('#route-choices').innerHTML=y.choices.map((c,i)=>`<button class="route-choice ${selected===c.id?'selected':''}" data-route="${E(c.id)}"><small>0${i+1}</small><strong>${E(c.label)}</strong><p>${E(c.story)}</p><span class="choice-effect">${Object.entries(c.effect||{}).map(([k,n])=>`${E(labels[k]||k)} ${n>=0?'+':''}${n}`).join(' · ')}</span></button>`).join('');$$('[data-route]').forEach(b=>b.addEventListener('click',()=>{P.choices[y.year]=b.dataset.route;save();pageSound();openChoices();renderFrames();}));const outcome=$('#choice-outcome');outcome.hidden=!selected;if(selected){const choice=y.choices.find(c=>c.id===selected),aftermath=choice?.outcome||`在“${y.title}”这一页，你决定${choice?.label||'留一点余地'}。这次选择进入了你的模拟行囊，后面的故事会带着它继续展开。`,all=route();outcome.innerHTML=`<p>${E(aftermath)}</p>${y.year===max?`<p>远景回望：你在 ${Object.keys(P.choices).length} 个年度留下了选择，模拟路线更常走向“${E(all.name)}”。2100 是本书的展示边界，你可以回头再走一次不同的支线。</p>`:''}<button class="ink-button" id="choice-next">${y.year===max?'回到世界地图':'带着这个选择，走向 '+(y.year+1)} <span>→</span></button>`;$('#choice-next').addEventListener('click',()=>{closeDialog('choice-dialog');if(y.year===max)showScreen('world');else{const layout=$('#comic-layout');if(!reduce){layout.classList.remove('flipping');void layout.offsetWidth;layout.classList.add('flipping');}enterYear(y.year+1);}});}openDialog('choice-dialog');}
function renderWorld(){const active=chapterIndex(current());$('#chapter-ribbon').innerHTML=chapters.map((d,i)=>`<button class="chapter-tile ${active===i?'active':''}" data-chapter="${i}"><img src="${E(chapterImage(i))}" alt="${E(d.title)}章节场景" loading="lazy"><span class="chapter-tile-text"><small>${d.startYear}—${Math.min(d.endYear,max)} · 第${String(i).padStart(2,'0')}章</small><strong>${E(d.title)}</strong></span>${chapterDone(d)?'<span class="chapter-cleared">已留痕</span>':''}</button>`).join('');$('#world-flat').innerHTML=chapters.map((d,i)=>`<button class="flat-page" data-chapter="${i}"><img src="${E(chapterImage(i))}" alt="${E(d.title)}的漫画场景" loading="lazy"><span><small>${d.startYear}—${Math.min(d.endYear,max)} · 虚岁${d.start}—${Math.min(d.end,max-min+1)}</small>${E(d.title)}</span></button>`).join('');$$('[data-chapter]').forEach(b=>b.addEventListener('click',()=>enterYear(chapters[Number(b.dataset.chapter)].startYear)));bindImages($('#world-screen'));setMapMode(state.mapMode);}
async function setMapMode(mode){state.mapMode=mode;$('#map-3d').classList.toggle('active',mode==='3d');$('#map-2d').classList.toggle('active',mode==='2d');$('#world-canvas').hidden=mode!=='3d';$('#world-flat').hidden=mode!=='2d';$('.world-rotate').hidden=mode!=='3d';$('#world-gesture').textContent=mode==='3d'?'拖动旋转书页 · 点击场景进入章节':'横向滑动书页 · 点击任意章节进入';if(mode==='2d'){$('#world-status').hidden=true;state.world?.setVisible(false);return;}if(state.world){state.world.setVisible(true);state.world.resize();$('#world-status').hidden=true;return;}$('#world-status').hidden=false;try{state.worldLoading ||= import('./world3d.js').then(m=>m.createWorld($('#world-canvas'),chapters,{image:chapterImage,onSelect:i=>enterYear(chapters[i].startYear),onUnavailable:()=>{$('#map-3d').disabled=true;$('#map-3d').title='当前空间渲染不可用，请使用平面地图。';setMapMode('2d');toast('空间渲染暂停，已切换平面地图。');},reduce}));state.world=await state.worldLoading;$('#world-status').hidden=true;state.world.setVisible(state.screen==='world'&&state.mapMode==='3d');state.world.resize();}catch(_){$('#world-status').hidden=true;state.mapMode='2d';$('#map-3d').disabled=true;setMapMode('2d');toast('当前设备改用平面地图，全部章节仍可进入。');}}
function openIndex(){$('#year-search').value=state.year;$('#index-grid').innerHTML=chapters.map((d,i)=>`<section class="index-chapter"><h3>${E(d.title)}<small>第${String(i).padStart(2,'0')}章 · ${d.startYear}—${Math.min(d.endYear,max)}</small></h3><div class="year-grid">${D.years.filter(y=>y.decadeId===d.id).map(y=>`<button class="${P.actions[y.year]?'has-memory':''} ${P.choices[y.year]?'chosen':''} ${state.year===y.year?'current':''}" data-year="${y.year}" title="${E(y.title)}">${y.year}</button>`).join('')}</div></section>`).join('');$$('[data-year]').forEach(b=>b.addEventListener('click',()=>enterYear(b.dataset.year)));openDialog('index-dialog');}
