function renderBag(){const years=D.years.filter(y=>P.actions[y.year]),chosen=Object.keys(P.choices).length,done=chapters.filter(chapterDone).length;$('#journey-count').textContent=`记忆 ${years.length} / 101 · 选择 ${chosen} · 章节 ${done} / 11`;$$('[data-bag-tab]').forEach(b=>{b.classList.toggle('active',b.dataset.bagTab===state.bagTab);b.setAttribute('aria-selected',String(b.dataset.bagTab===state.bagTab));});const content=$('#bag-content');if(state.bagTab==='memories'){content.innerHTML=years.length?`<div class="memory-grid">${years.map(y=>{const m=comicFor(y).memory||{name:`${y.year}的一页纸`,description:y.title};return`<button class="memory-card" data-memory-year="${y.year}"><img src="${E(yearScene(y))}" alt="${E(m.name)}记忆卡" loading="lazy"><small>${y.year}</small><strong>${E(m.name)}</strong><p>${E(m.description)}</p></button>`;}).join('')}</div>`:'<div class="empty-bag">行囊还是空的。<br>走进任意一年，做一个动作，收下第一件记忆。</div>';$$('[data-memory-year]').forEach(b=>b.addEventListener('click',()=>enterYear(b.dataset.memoryYear)));}else if(state.bagTab==='badges'){content.innerHTML=`<div class="badge-grid">${chapters.map((d,i)=>{const ys=D.years.filter(y=>y.decadeId===d.id),count=ys.filter(y=>P.actions[y.year]&&P.choices[y.year]).length;return`<div class="badge-card ${chapterDone(d)?'earned':''}"><i>${String(i).padStart(2,'0')}</i><strong>${E(d.title)}</strong><small>${chapterDone(d)?'章节记忆已完整收起':`动作＋选择 ${count} / ${ys.length}`}<br>${d.startYear}—${Math.min(d.endYear,max)}</small></div>`;}).join('')}</div>`;}else{const r=route(),description={explore:'你在模拟里经常先走向陌生处，用新环境和小试验，替下一步找到坐标。熟悉的地方也可以因为一个新问题而重新变大。',deepen:'你在模拟里经常把注意力放回手中的事，让零散经验沉淀成能反复使用的结构。一件完整的小作品，是你给时间留下的回声。',connect:'你在模拟里经常先寻找可以并肩的人，在相处、倾听和协作里理解自己的需求。你的路线把关系当成共同体验的空间。'}[r.id]||'角色的形状还没有被写下。你在每一年选择开拓、深耕或关系，路线会慢慢呈现。它描述游戏里的选择，不定义现实中的你。';content.innerHTML=`<div class="character-layout"><div class="character-portrait"><img src="assets/portrait.jpg" alt="漫画中的主人公角色肖像"></div><div class="character-copy"><span class="small-label">YOUR SIMULATED CHARACTER</span><h3>${E(r.name)}</h3><p>${E(description)}</p><div class="role-counts"><span><b>${r.counts.explore}</b>次开拓</span><span><b>${r.counts.deepen}</b>次深耕</span><span><b>${r.counts.connect}</b>次关系</span></div><div class="character-stats">${dimensions.map(d=>`<span>${E(d.label)}<b>${r.bag[d.key]>=0?'+':''}${r.bag[d.key]}</b></span>`).join('')}</div><p class="fine-note">这些数值仅为模拟行囊；不会修改命盘或六维原始曲线。</p></div></div>`;}bindImages(content);}
function sharpFor(y){return window.SHARP_DATA?.years?.[y.year]||{};}
function mutationBadge(type,prefix='生年'){return type?`<small class="mutation-badge mut-${E(type)}" title="${E(prefix)}化${E(type)}">${E(prefix)}${E(type)}</small>`:'';}
function renderStars(){const y=current(),soul=D.palaces.find(p=>p.name==='命宫'),decadal=D.palaces.find(p=>p.name===y.decadalPalace),annual=D.palaces.find(p=>p.name===y.annualPalace);const layers=[{key:'natal',name:'本命命宫',scope:'原局',palace:soul,mutations:y.natalMutations},{key:'decadal',name:(y.scopeName||'大限')+'命宫',scope:`${y.decadalStem||''}${y.decadalBranch||''} · 叠本命${y.decadalPalace}`,palace:decadal,mutations:y.decadalMutations},{key:'yearly',name:'流年命宫',scope:`${y.stem}${y.branch} · 叠本命${y.annualPalace}`,palace:annual,mutations:y.annualMutations}];$('#star-layers').innerHTML=layers.map(layer=>{const p=layer.palace;if(!p)return'';const borrowed=!p.major.length,source=borrowed?D.palaces.find(x=>x.index===(p.index+6)%12):p;return`<div class="star-layer layer-${layer.key}"><div class="star-layer-label"><strong>${E(layer.name)}</strong><span>${E(layer.scope)} · ${E(p.stem)}${E(p.branch)}</span></div>${borrowed?`<span class="empty-palace">本宫无十四主星 · 对宫${E(source?.name||'')}作参照</span>`:''}<div class="star-layer-stars ${borrowed?'borrowed-stars':''}">${A(source?.major).map(star=>`<button class="main-star" data-star="${E(star.name)}" data-star-layer="${layer.key}" aria-label="查看${E(star.name)}的宫位与四化依据"><span>${E(star.name)}</span><small class="star-brightness">${E(star.brightness||'未列')}</small>${mutationBadge(star.mutagen)}${layer.key==='natal'?'':A(layer.mutations).filter(m=>m.star===star.name).map(m=>mutationBadge(m.type,layer.key==='yearly'?'流年':y.scopeName||'大限')).join('')}<i>↗</i></button>`).join('')}</div><div class="layer-transform-list">${A(layer.mutations).slice().sort((a,b)=>'禄权科忌'.indexOf(a.type)-'禄权科忌'.indexOf(b.type)).map(m=>`<span>${E(m.star)}${mutationBadge(m.type,layer.key==='natal'?'生年':layer.key==='yearly'?'流年':y.scopeName||'大限')}</span>`).join('')}</div></div>`;}).join('');$$('[data-star]').forEach(b=>b.addEventListener('click',()=>openStar(b.dataset.star,b.dataset.starLayer)));}
function openStar(name,layer){const y=current(),p=D.palaces.find(p=>p.major.some(s=>s.name===name)),star=p?.major.find(s=>s.name===name);if(!p||!star)return;const trines=[p.index,(p.index+4)%12,(p.index+8)%12,(p.index+6)%12].map(index=>D.palaces.find(p=>p.index===index));const scopeNames={natal:'本命命宫',decadal:(y.scopeName||'大限')+'命宫',yearly:'流年命宫'};const layers=[{name:'生年四化',mutations:y.natalMutations},{name:(y.scopeName||'大限')+'四化',mutations:y.decadalMutations},{name:`${y.year}流年四化`,mutations:y.annualMutations}];$('#star-dialog-title').innerHTML=`<span>${E(name)}</span><small>${E(star.brightness||'未列亮度')}</small>${mutationBadge(star.mutagen)}`;$('#star-dialog-content').innerHTML=`<p class="star-context">从${E(scopeNames[layer])}查看 · 当前${y.year}年</p><p><strong>原局位置：</strong>${E(p.stem)}${E(p.branch)} · 本命${E(p.name)}${p.isBody?'，同时为身宫':''}。亮度“${E(star.brightness||'未列')}”与生年化曜均取原局，不把流年四化混成生年性质。</p><h3>这颗星，在三层四化里怎样被引动</h3><div class="star-mutation-layers">${layers.map(l=>{const matching=A(l.mutations).filter(m=>m.star===name);return`<div><strong>${E(l.name)}</strong>${matching.length?matching.map(m=>`<p>${mutationBadge(m.type,l.name.includes('生年')?'生年':l.name.includes('流年')?'流年':y.scopeName||'大限')} ${E(name)}化${E(m.type)}，落本命${E(m.natalPalace)}${m.annualPalace?`，叠流年${E(m.annualPalace)}`:''}${m.decadalPalace?`，叠${E(y.scopeName||'大限')}${E(m.decadalPalace)}`:''}。</p>`).join(''):`<p>本层未使${E(name)}化禄、权、科、忌；不据此等同没有影响。</p>`}</div>`;}).join('')}</div><h3>所在本命宫的三方四正</h3><div class="star-trine-grid">${trines.map((palace,i)=>`<div><span>${i===0?'本宫':i===3?'对宫':'三合宫'}</span><strong>${E(palace.stem)}${E(palace.branch)} · ${E(palace.name)}</strong><p>${palace.major.length?palace.major.map(s=>`${E(s.name)}（${E(s.brightness||'未列')}）${s.mutagen?' · 生年'+E(s.mutagen):''}`).join('、'):'无十四主星'}</p></div>`).join('')}</div><p class="fine-note">这里列的是原局宫位结构。年度判断还要区分流年宫与大限宫，不能将一个化忌或单颗主星直接对应到确定事件。</p>`;openDialog('star-dialog');}
function renderSharp(){const y=current(),sharp=sharpFor(y),section=$('#sharp-verdict');if(!sharp.headline){section.hidden=true;return;}const compact=matchMedia('(max-width:620px)').matches;section.hidden=false;section.innerHTML=`<div class="sharp-heading"><span class="sharp-year">${y.year} / 本年判断</span><h2>${E(sharp.headline)}</h2></div><details class="sharp-detail" ${compact?'':'open'}><summary>今年主攻什么，代价与避坑在哪里 <span>↗</span></summary><p class="sharp-verdict-copy">${E(sharp.verdict||'')}</p><div class="sharp-angles"><div><span>主攻</span><p>${E(sharp.upside||'')}</p></div><div><span>代价</span><p>${E(sharp.price||'')}</p></div><div><span>避坑</span><p>${E(sharp.pitfall||'')}</p></div></div><details class="sharp-audit"><summary>看判断的抓手与验证信号 <span>↗</span></summary>${sharp.watch?`<p><strong>现实中看什么：</strong>${E(sharp.watch)}</p>`:''}<ul>${A(sharp.claimBasis).map(b=>`<li>${E(typeof b==='string'?b:b.text||b.claim||JSON.stringify(b))}</li>`).join('')}</ul></details></details>`;}

const trendLines=[{key:'opportunity',label:'机会',color:'#4d8567'},{key:'pressure',label:'阻力',color:'#b14c38'},{key:'balance',label:'净势',color:'#304f63'}];
const trendState={scale:'dramatic',range:matchMedia('(max-width:620px)').matches?'near':'all',selected:null,visible:new Set(trendLines.map(d=>d.key)),open:false};
function trendRaw(y,key){const trend=sharpFor(y).trend;if(!trend)return null;const value=trend.raw?.[key]??trend[key];return typeof value==='number'&&Number.isFinite(value)?value:null;}
function trendDisplay(raw){return trendState.scale==='dramatic'?50+50*Math.tanh(3*(raw-50)/50):raw;}
function trendRange(){if(trendState.range==='near'){let start=Math.max(min,(trendState.selected??state.year)-5),end=Math.min(max,start+11);start=Math.max(min,end-11);return[start,end];}return[min,max];}
function trendMethodMarkup(){const m=window.SHARP_DATA?.trendMetadata;if(!m)return'';const keys=[['ledger','先分开机会与成本'],['context','三层宫位怎样计入'],['stack','叠化怎样处理'],['major','主星怎样进入模型'],['raw','原始比较标尺'],['driverUnits','贡献数值的单位']];return `<details class="trend-method"><summary>曲线为什么这样起伏：账本、权重与完整数据 ↗</summary><p>${E(m.nature||'')}</p>${keys.map(([key,title])=>`<h4>${title}</h4><p>${E(m.formula?.[key]||'')}</p>`).join('')}<details><summary>固定权重表</summary><pre>${E(JSON.stringify(m.rules||{},null,2))}</pre></details><p><a href="trend-audit.json" download>下载101年完整底账与全部贡献 JSON ↗</a> · <a href="sharp-data.json" download>下载逐年判断与曲线 JSON ↗</a></p></details>`;}
function renderTrends(){const content=$('#trend-content');if(!trendState.open){content.hidden=true;return;}content.hidden=false;const selected=trendState.selected??state.year;trendState.selected=selected;const any=D.years.some(y=>trendRaw(y,'balance')!==null);if(!any){content.innerHTML='<p class="trend-missing">年势的可复核数据尚未载入。已有漫画与资料馆仍可继续探索。</p>';return;}content.innerHTML=`<div class="trend-controls"><div class="trend-legend">${trendLines.map(d=>`<button data-trend-line="${d.key}" class="${trendState.visible.has(d.key)?'active':''}" aria-pressed="${trendState.visible.has(d.key)}"><i style="background:${d.color}"></i>${d.label}</button>`).join('')}</div><div class="trend-switches"><div role="group" aria-label="曲线刻度"><button data-trend-scale="dramatic" class="${trendState.scale==='dramatic'?'active':''}">戏剧刻度</button><button data-trend-scale="raw" class="${trendState.scale==='raw'?'active':''}">原始刻度</button></div><div role="group" aria-label="曲线时间范围"><button data-trend-range="all" class="${trendState.range==='all'?'active':''}">101年</button><button data-trend-range="near" class="${trendState.range==='near'?'active':''}">附近12年</button></div></div></div><div class="trend-svg-wrap" id="trend-svg-wrap"><svg id="main-trend-svg" viewBox="0 0 1120 330" role="img" aria-label="机会、阻力与净势的逐年叙事信号曲线"></svg><div id="main-trend-tooltip" class="main-trend-tooltip" hidden></div></div><div class="trend-formula"><div><span>${trendState.scale==='dramatic'?'中央 3× · 极值平滑':'原始显示 · 不做视觉放大'}</span><details class="trend-transformation"><summary>展开显示公式</summary><code>${trendState.scale==='dramatic'?'display(v) = 50 + 50 × tanh(3 × (v − 50) / 50)':'display(v) = v'}</code><p>v 是模型的原始比较指数。机会／阻力两本底账用固定101年共享标尺映射至25—75；净势以50表示两账相等。显示变换不改变峰谷排序或权重。</p></details></div><span>非概率、收益或现实表现；峰谷均可点选追溯依据。</span></div><div class="trend-drivers" id="trend-drivers"></div>${trendMethodMarkup()}`;drawTrendSVG();renderTrendDrivers();$$('[data-trend-line]').forEach(b=>b.addEventListener('click',()=>{const key=b.dataset.trendLine;if(trendState.visible.has(key)){if(trendState.visible.size===1)return;trendState.visible.delete(key);}else trendState.visible.add(key);renderTrends();}));$$('[data-trend-scale]').forEach(b=>b.addEventListener('click',()=>{trendState.scale=b.dataset.trendScale;renderTrends();}));$$('[data-trend-range]').forEach(b=>b.addEventListener('click',()=>{trendState.range=b.dataset.trendRange;renderTrends();}));const svg=$('#main-trend-svg');svg.addEventListener('mousemove',showTrendTooltip);svg.addEventListener('mouseleave',()=>$('#main-trend-tooltip').hidden=true);svg.addEventListener('click',event=>{trendState.selected=trendEventYear(event);drawTrendSVG();renderTrendDrivers();});}
function drawTrendSVG(){const[from,to]=trendRange(),ys=D.years.filter(y=>y.year>=from&&y.year<=to),w=Math.max(320,Math.min(1120,Math.round($('#trend-svg-wrap').clientWidth))),h=330,l=34,r=22,t=31,b=34,X=year=>l+(year-from)/(to-from||1)*(w-l-r),Y=value=>t+(100-value)/100*(h-t-b);let html='';for(const n of[0,25,50,75,100])html+=`<line x1="${l}" x2="${w-r}" y1="${Y(n)}" y2="${Y(n)}" class="trend-grid ${n===50?'trend-midline':''}"/><text x="1" y="${Y(n)+4}" class="trend-axis">${n}</text>`;const step=trendState.range==='all'?(w<600?20:10):2;for(let year=Math.ceil(from/step)*step;year<=to;year+=step)html+=`<text x="${X(year)}" y="${h-9}" class="trend-axis" text-anchor="${year===from?'start':year===to?'end':'middle'}">${year}</text>`;for(const d of chapters)if(d.startYear>from&&d.startYear<to)html+=`<line x1="${X(d.startYear)}" x2="${X(d.startYear)}" y1="${t}" y2="${h-b}" class="trend-chapter-line"/>`;for(const line of trendLines.filter(d=>trendState.visible.has(d.key))){let path='',connected=false;for(const y of ys){const raw=trendRaw(y,line.key);if(raw===null){connected=false;continue;}path+=`${connected?'L':'M'}${X(y.year).toFixed(2)} ${Y(trendDisplay(raw)).toFixed(2)} `;connected=true;}html+=`<path d="${path}" stroke="${line.color}" class="trend-curve" style="stroke-width:${line.key==='balance'?3.2:2.15}"/>`;}
 const net=ys.filter(y=>trendRaw(y,'balance')!==null),peak=net.reduce((a,y)=>!a||trendRaw(y,'balance')>trendRaw(a,'balance')?y:a,null),valley=net.reduce((a,y)=>!a||trendRaw(y,'balance')<trendRaw(a,'balance')?y:a,null);for(const[y,label,delta]of[[peak,'净势峰',-12],[valley,'净势谷',20]])if(y&&trendState.visible.has('balance')&&(label==='净势峰'||y.year!==peak?.year)){const value=trendDisplay(trendRaw(y,'balance')),cx=X(y.year),cy=Y(value);html+=`<circle cx="${cx}" cy="${cy}" r="4" fill="#304f63" stroke="#f7f1e2" stroke-width="2"/><text x="${Math.max(65,Math.min(w-65,cx))}" y="${Math.max(15,Math.min(h-44,cy+delta))}" text-anchor="middle" class="trend-extreme">${label} ${y.year}</text>`;}
 const selected=trendState.selected??state.year;if(selected>=from&&selected<=to){html+=`<line x1="${X(selected)}" x2="${X(selected)}" y1="${t}" y2="${h-b}" class="trend-selected"/>`;for(const line of trendLines.filter(d=>trendState.visible.has(d.key))){const raw=trendRaw(getYear(selected),line.key);if(raw!==null)html+=`<circle cx="${X(selected)}" cy="${Y(trendDisplay(raw))}" r="4.5" fill="${line.color}" stroke="#f7f1e2" stroke-width="2"/>`;}html+=`<rect x="${X(selected)-21}" y="${h-26}" width="42" height="22" fill="#e0d5b9"/><text x="${X(selected)}" y="${h-10}" text-anchor="middle" class="trend-axis" style="fill:#5e634d;font-weight:600">${selected}</text>`;}$('#main-trend-svg').setAttribute('viewBox',`0 0 ${w} ${h}`);$('#main-trend-svg').innerHTML=html;}
function trendEventYear(event){const[from,to]=trendRange(),svg=$('#main-trend-svg'),rect=svg.getBoundingClientRect(),w=svg.viewBox.baseVal.width||1120,x=(event.clientX-rect.left)/rect.width*w;return Math.max(from,Math.min(to,Math.round(from+(x-34)/(w-56)*(to-from))));}
function showTrendTooltip(event){const year=trendEventYear(event),y=getYear(year),tip=$('#main-trend-tooltip'),wrap=$('#trend-svg-wrap').getBoundingClientRect();tip.innerHTML=`<strong>${year}</strong><span>${E(sharpFor(y).headline||y.title)}</span>${trendLines.filter(d=>trendState.visible.has(d.key)).map(d=>{const raw=trendRaw(y,d.key);return`<div><i style="background:${d.color}"></i>${d.label}<b>${raw===null?'未载入':trendDisplay(raw).toFixed(1)}</b><small>${raw===null?'':'原始 '+raw.toFixed(1)}</small></div>`;}).join('')}`;tip.style.left=Math.max(0,Math.min(wrap.width-235,event.clientX-wrap.left+13))+'px';tip.hidden=false;}
function renderTrendDrivers(){const y=getYear(trendState.selected??state.year),sharp=sharpFor(y),trend=sharp.trend||{},drivers=A(trend.drivers);$('#trend-drivers').innerHTML=`<div class="trend-driver-heading"><div><span>${y.year} · 虚岁${y.nominalAge}</span><h3>${E(sharp.headline||y.title)}</h3></div><button class="ink-button" id="trend-enter-year">进入${y.year}的漫画 <span>→</span></button></div><div class="trend-values">${trendLines.map(d=>{const raw=trendRaw(y,d.key);return`<span style="--trend-color:${d.color}"><strong>${d.label}</strong><b>${raw===null?'—':trendDisplay(raw).toFixed(1)}</b><small>原始 ${raw===null?'未载入':raw.toFixed(2)}</small></span>`;}).join('')}</div><ul>${drivers.map(driver=>`<li>${E(typeof driver==='string'?driver:driver.text||driver.reason||JSON.stringify(driver))}</li>`).join('')}</ul>${!drivers.length?'<p class="fine-note">此年的贡献说明尚未载入，不据空白推断为无波折。</p>':''}`;$('#trend-enter-year').addEventListener('click',()=>enterYear(y.year));}
function toggleTrends(force){trendState.open=typeof force==='boolean'?force:!trendState.open;$('#toggle-trends').setAttribute('aria-expanded',String(trendState.open));$('#toggle-trends strong').textContent=trendState.open?'收起年势 −':'展开年势 ↗';if(trendState.open)trendState.selected=state.year;renderTrends();}

function openEvidence(){const y=current();$('#evidence-title').textContent=`${y.year} · 这一年的斗数线索`;$('#archive-year-link').href=`archive.html?year=${y.year}`;$('#evidence-content').innerHTML=`<p>${E(y.startDate)} 至 ${E(y.endBefore)} 前一日。${E(y.stem)}${E(y.branch)}年，虚岁${y.nominalAge}。流年命宫叠本命${E(y.annualPalace)}，${E(y.scopeName||'大限')}${E(y.decadalStem)}${E(y.decadalBranch)}叠本命${E(y.decadalPalace)}。</p><h3>流年四化</h3><table><thead><tr><th>化曜</th><th>本命宫</th><th>流年宫</th><th>${E(y.scopeName||'大限')}宫</th></tr></thead><tbody>${y.annualMutations.map(m=>`<tr><td>${E(m.star)}化${E(m.type)}</td><td>${E(m.natalPalace)}</td><td>${E(m.annualPalace)}</td><td>${E(m.decadalPalace)}</td></tr>`).join('')}</tbody></table><details><summary>这张年度插画，为什么这样画</summary><p>本年专属图：${E(y.year)} · ${E(y.title)}。画面围绕当年的命宫结构、四化与下面三段剧情独立生成；人物与事件是虚构情境。</p><ol>${A(comicFor(y).dialogue).map(s=>`<li>${E(s)}</li>`).join('')}</ol><a href="art-index.json" download>下载101年插画与排盘依据对照 ↗</a></details><h3>六个切面的可复核依据</h3>${dimensions.map(d=>{const evidence=y.evidence.find(e=>e.dimension===d.key),details=y.scoreDetails[d.key];return`<details><summary>${E(d.label)} · 编辑指数 ${y.scores[d.key]}</summary><p>${E(y.aspects[d.key])}</p><p>${E(evidence?.text)}</p><p>起点50 → 原始值${Number(details.raw).toFixed(3)} → 显示值${details.value}</p><ul>${details.trace.map(t=>`<li>${E(t)}</li>`).join('')}</ul></details>`;}).join('')}<p class="fine-note">完整十二宫、三方四正、生年／大限／流年四化、101年曲线、计分公式与原始JSON均在资料馆。</p>`;openDialog('evidence-dialog');}
function syncCurrentScreen(){if(state.screen==='play'){renderPlay();history.replaceState(null,'',`#year-${state.year}`);}else if(state.screen==='world')renderWorld();else renderCover();}
function exportSave(){const blob=new Blob([JSON.stringify({...P,title:'此生·交互漫画存档',exportedAt:new Date().toISOString()},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='cisheng-comic-save.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('这段旅程，已经存进文件。');}
async function importSave(file){if(!file)return;try{if(file.size>262144)throw new Error('文件超过256KB，请选择本游戏导出的存档。');const clean=cleanSave(JSON.parse(await file.text()),true);Object.assign(P,clean);save();state.year=P.lastYear;state.frame=P.frames[state.year]??0;syncCurrentScreen();renderBag();toast(`已接回 ${Object.keys(P.choices).length} 次选择与 ${Object.values(P.actions).filter(Boolean).length} 件记忆。`);}catch(e){toast(e instanceof SyntaxError?'文件不是有效JSON，原存档未改变。':e.message);}finally{$('#save-file').value='';}}
